// Package assets embeds the popcorn icons (generated by tools/genicon).
package assets

import (
	_ "embed"
	"runtime"
)

var (
	//go:embed tray.ico
	trayICO []byte
	//go:embed tray-paused.ico
	trayPausedICO []byte
	//go:embed tray.png
	trayPNG []byte
	//go:embed tray-paused.png
	trayPausedPNG []byte
	//go:embed tray-request.ico
	trayRequestICO []byte
	//go:embed tray-request.png
	trayRequestPNG []byte

	//go:embed icon-128.png
	Icon128 []byte
	// KnockSound plays for the sharer when someone asks to join; JoinSound
	// plays in viewers' browsers when another friend starts watching.
	//go:embed notification-sound.wav
	KnockSound []byte
	//go:embed join-sound.wav
	JoinSound []byte

	// Backgrounds of the viewer page's name and goodbye screens: full for
	// computers (with low, the same picture smaller, shown while it loads)
	// and mobile for phones held upright.
	//go:embed background-full.jpg
	BackgroundFull []byte
	//go:embed background-low.jpg
	BackgroundLow []byte
	//go:embed background-mobile.jpg
	BackgroundMobile []byte

	// Guide is the "How it works" page; {{ICON}} is replaced with Icon128.
	//go:embed guide.html
	Guide []byte
)

// ViewerFiles are served next to the viewer page.
func ViewerFiles() map[string][]byte {
	return map[string][]byte{
		"join-sound.wav":        JoinSound,
		"background-full.jpg":   BackgroundFull,
		"background-low.jpg":    BackgroundLow,
		"background-mobile.jpg": BackgroundMobile,
	}
}

// Tray icon variants.
const (
	TrayNormal  = iota
	TrayPaused  // greyed out: not sharing, or paused
	TrayRequest // blue dot: someone is waiting to be let in
)

// Tray returns the tray icon in the format the OS tray expects (ICO on
// Windows, PNG elsewhere).
func Tray(variant int) []byte {
	ico := [...][]byte{trayICO, trayPausedICO, trayRequestICO}
	png := [...][]byte{trayPNG, trayPausedPNG, trayRequestPNG}
	if runtime.GOOS == "windows" {
		return ico[variant]
	}
	return png[variant]
}
